sys_script_include.script:
var CourseUtils = Class.create();
CourseUtils.prototype = {
    initialize: function() {},

    // Verifica se o usuário já se matriculou no curso mais de 3 vezes
    hasExceededEnrollmentLimit: function(userSysId, courseSysId) {
        var grEnrollment = new GlideRecord("x_1593182_course_0_course_schedule");
        grEnrollment.addQuery("course", courseSysId);
        grEnrollment.addQuery("opened_by", userSysId);
        grEnrollment.query();

        var count = 0;
        while (grEnrollment.next()) {
            count++;
            if (count >= 3) {
                return true; // O usuário já atingiu o limite de 3 inscrições
            }
        }
        return false;
    },

    // Verifica se ainda há vagas no treinamento
    isTrainingFull: function(courseScheduleSysId) {
        var grSchedule = new GlideRecord("x_1593182_course_0_course_schedule");
        if (grSchedule.get(courseScheduleSysId)) {
            var maxCapacity = grSchedule.max_capacity; // Certifique-se de que este campo existe na tabela
            var enrolledCount = grSchedule.enrolled_count; // Número de inscritos
            return enrolledCount >= maxCapacity; // Retorna true se já atingiu a lotação máxima
        }
        return false;
    },

    // Verifica se o usuário é o instrutor do treinamento
    isUserInstructor: function(userSysId, courseScheduleSysId) {
        var grSchedule = new GlideRecord("x_1593182_course_0_course_schedule");
        if (grSchedule.get(courseScheduleSysId)) {
            return grSchedule.instructor == userSysId; // Retorna true se o usuário for o instrutor
        }
        return false;
    },

    // Verifica se o treinamento está no prazo permitido para matrícula (até 1 dia antes)
    isRegistrationClosed: function(courseScheduleSysId) {
        var grSchedule = new GlideRecord("x_1593182_course_0_course_schedule");
        if (grSchedule.get(courseScheduleSysId)) {
            var today = new GlideDate();
            var trainingDate = new GlideDate();
            trainingDate.setValue(grSchedule.course_date);

            today.addDaysLocalTime(1); // Adiciona um dia à data atual para comparação
            return today.compareTo(trainingDate) >= 0; // Retorna true se já passou do prazo
        }
        return false;
    },

    // Método principal para verificar todas as regras ao mesmo tempo
    validateEnrollment: function(userSysId, courseSysId, courseScheduleSysId) {
        if (this.hasExceededEnrollmentLimit(userSysId, courseSysId)) {
            return "Limite de 3 matrículas por curso atingido.";
        }
        if (this.isTrainingFull(courseScheduleSysId)) {
            return "Treinamento já atingiu a lotação máxima.";
        }
        if (this.isUserInstructor(userSysId, courseScheduleSysId)) {
            return "Instrutores não podem se inscrever em seus próprios treinamentos.";
        }
        if (this.isRegistrationClosed(courseScheduleSysId)) {
            return "Matrículas encerradas. Você só pode se matricular até 1 dia antes do treinamento.";
        }
        return "OK"; // Todas as regras passaram, pode se matricular
    },

    type: "CourseUtils"
};
